package run.ikaros.finance; import java.time.Instant; import java.util.UUID; import org.springframework.stereotype.Service; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; import run.ikaros.common.NotFoundException; @Service public class TransactionTemplateService{private final LedgerRepository ledgers;private final AccountRepository accounts;private final TransactionTemplateRepository templates;public TransactionTemplateService(LedgerRepository l,AccountRepository a,TransactionTemplateRepository t){ledgers=l;accounts=a;templates=t;}public Mono<TransactionTemplateView> create(UUID a,UUID l,CreateTransactionTemplateRequest q){if(q.amount()!=null&&q.amount().signum()<0)return Mono.error(new IllegalArgumentException("模板金额不能为负"));return own(a,l).flatMap(x->accounts.findById(q.accountId()).filter(ac->ac.ownerId().equals(a)&&ac.ledgerId().equals(l)).switchIfEmpty(Mono.error(new NotFoundException("Account 不存在或不属于该 Ledger"))).flatMap(ac->templates.save(new TransactionTemplateEntity(null,l,a,q.name().trim(),q.type(),q.accountId(),q.targetAccountId(),q.amount(),q.currency()==null?ac.currency():q.currency().toUpperCase(),q.categoryId(),q.payee(),q.note(),false,Instant.now(),Instant.now(),null)))).map(this::view);}public Flux<TransactionTemplateView> list(UUID a,UUID l){return own(a,l).flatMapMany(x->templates.findAllByLedgerIdAndOwnerIdAndArchivedFalseOrderByNameAsc(l,a).map(this::view));}public Mono<TransactionTemplateView> archive(UUID a,UUID id){return templates.findById(id).filter(t->t.ownerId().equals(a)).switchIfEmpty(Mono.error(new NotFoundException("Transaction Template 不存在或无权访问"))).flatMap(t->templates.save(new TransactionTemplateEntity(t.id(),t.ledgerId(),t.ownerId(),t.name(),t.type(),t.accountId(),t.targetAccountId(),t.amount(),t.currency(),t.categoryId(),t.payee(),t.note(),true,t.createdAt(),Instant.now(),t.version()))).map(this::view);}private Mono<LedgerEntity> own(UUID a,UUID l){return ledgers.findById(l).filter(x->x.ownerId().equals(a)).switchIfEmpty(Mono.error(new NotFoundException("Ledger 不存在或无权访问")));}private TransactionTemplateView view(TransactionTemplateEntity t){return new TransactionTemplateView(t.id(),t.ledgerId(),t.name(),t.type(),t.accountId(),t.targetAccountId(),t.amount(),t.currency(),t.categoryId(),t.payee(),t.note(),t.archived(),t.createdAt());}}
